#!/usr/bin/env python3
"""Wrapper to run eva_glm_steering_generation.py from host Python."""

import subprocess
import sys

SUFFIX = ("CACUAAUAAAAAAACACACAAGCGACAGUGUGUACAAUGGACAUUGCCAGCACUCCAGGCAG"
          "")

def main():
    cmd = [
        "docker", "run", "--rm", "--gpus", "device=1",
        "-v", "/data/yanjie_huang/eva/EVA1:/eva",
        "-v", "/data/yanjie_huang/rna_benchmark:/data/yanjie_huang/rna_benchmark",
        "-w", "/eva",
        "--name", "eva_steer_gen_full",
        "eva:latest",
        "/composer-python/python",
        "/eva/scripts/sae_feature_steering/eva_glm_steering_generation.py",
        "--checkpoint", "/eva/checkpoint/clm",
        "--sae", "/eva/data/sae_feature_steering/sae_evo2_online_1400M_final.pt",
        "--device", "cuda:0",
        "--layer", "13",
        "--prefix", "AGGAAAUUCCAUUUGGCUGCAGCUUCUGGACGACAGGAGACGUGGGGAGACGGCCACCAUG",
        "--suffix", SUFFIX,
        "--feature-id", "4086",
        "--scales", "0,1,2",
        "--num-samples", "20",
        "--max-gen-length", "64",
        "--temperature", "0.7",
        "--out-prefix", "/eva/data/sae_feature_steering/results/eva_steering_generation_full",
        "--seed", "42",
    ]
    result = subprocess.run(cmd)
    sys.exit(result.returncode)

if __name__ == "__main__":
    main()
